import{_ as a,o as i,c as e,ao as t}from"./chunks/framework.Dz-3nxMo.js";const c=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting_started.md","filePath":"getting_started.md","lastUpdated":null}'),l={name:"getting_started.md"};function n(p,s,h,r,o,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="Getting-Started" tabindex="-1">Getting Started <a class="header-anchor" href="#Getting-Started" aria-label="Permalink to &quot;Getting Started {#Getting-Started}&quot;">​</a></h1><h2 id="Install" tabindex="-1">Install <a class="header-anchor" href="#Install" aria-label="Permalink to &quot;Install {#Install}&quot;">​</a></h2><p>These steps assume that you have not used Julia much. You do them once.</p><h3 id="1.-Install-Julia" tabindex="-1">1. Install Julia <a class="header-anchor" href="#1.-Install-Julia" aria-label="Permalink to &quot;1. Install Julia {#1.-Install-Julia}&quot;">​</a></h3><p>Timekeepers.jl needs Julia 1.12 or newer. Install it with juliaup, the official installer:</p><ul><li><p><strong>macOS and Linux</strong>: in a terminal, run <code>curl -fsSL https://install.julialang.org | sh</code></p></li><li><p><strong>Windows</strong>: in a terminal, run <code>winget install --name Julia --id 9NJNWW8PVKMN -e -s msstore</code></p></li></ul><p>Close the terminal, open a new one, and check the version with <code>julia --version</code>.</p><h3 id="2.-Get-Timekeepers.jl" tabindex="-1">2. Get Timekeepers.jl <a class="header-anchor" href="#2.-Get-Timekeepers.jl" aria-label="Permalink to &quot;2. Get Timekeepers.jl {#2.-Get-Timekeepers.jl}&quot;">​</a></h3><p>Timekeepers.jl is not in the Julia package registry yet, so get it from GitHub. With git:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/JuliaGeophysics/Timekeepers.jl</span></span></code></pre></div><p>Without git, open <a href="https://github.com/JuliaGeophysics/Timekeepers.jl" target="_blank" rel="noreferrer">https://github.com/JuliaGeophysics/Timekeepers.jl</a>, click <strong>Code</strong>, then <strong>Download ZIP</strong>, and unzip it.</p><h3 id="3.-Install-its-packages" tabindex="-1">3. Install its packages <a class="header-anchor" href="#3.-Install-its-packages" aria-label="Permalink to &quot;3. Install its packages {#3.-Install-its-packages}&quot;">​</a></h3><p>In a terminal, go into the folder and start Julia in it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Timekeepers.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auto</span></span></code></pre></div><p><code>--project=.</code> tells Julia to use the packages of this folder. <code>-t auto</code> lets the windows stay live while they work.</p><p>Julia shows the <code>julia&gt;</code> prompt. Type <code>]</code> (a closing square bracket). The prompt changes to <code>(Timekeepers) pkg&gt;</code>: this is the package mode. Type <code>instantiate</code> and press Enter:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-pkg">(Timekeepers) pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-pkg">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> instantiate</span></span></code></pre></div><p>Julia downloads and compiles about 290 packages, most of them for the graphics. This takes several minutes, only the first time. When it is done, press Backspace to go back to <code>julia&gt;</code>.</p><h3 id="4.-Check-that-windows-open" tabindex="-1">4. Check that windows open <a class="header-anchor" href="#4.-Check-that-windows-open" aria-label="Permalink to &quot;4. Check that windows open {#4.-Check-that-windows-open}&quot;">​</a></h3><p>TKDash, TKApp and TKProc open windows, so they need a desktop with OpenGL 3.3 or newer. At the <code>julia&gt;</code> prompt, type:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GLMakie</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">display</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">scatter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>If a window with ten dots opens, you are ready.</p><div class="tip custom-block"><p class="custom-block-title">Use Timekeepers.jl in your own project</p><p>If you have your own Julia project, you can add Timekeepers.jl to it instead of steps 2 and 3. Start Julia in your project, type <code>]</code>, then:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-pkg">pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-pkg">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> add https</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">github</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JuliaGeophysics</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Timekeepers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">jl</span></span></code></pre></div></div><h2 id="Use" tabindex="-1">Use <a class="header-anchor" href="#Use" aria-label="Permalink to &quot;Use {#Use}&quot;">​</a></h2><p>Each time, start Julia in the Timekeepers.jl folder as in step 3 (<code>julia --project=. -t auto</code>), then load the package and open a window:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Timekeepers</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">run_tkdash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/survey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. see which sites recorded together</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">run_tkapp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/LEMI090.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. clean one recording or site</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">run_tkproc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/survey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. estimate the transfer functions of its sites</span></span></code></pre></div><p>Replace the paths with the paths of your data. Each window stays open until you close it. Then the <code>julia&gt;</code> prompt comes back.</p><ul><li><p><a href="./tkdash">TKDash</a>: find the base and remote sites of each site in a survey</p></li><li><p><a href="./tkapp">TKApp</a>: mask bad intervals and write clean data</p></li><li><p><a href="./tkproc">TKProc</a>: estimate the impedance and the tipper, and write EDI files</p></li></ul><h2 id="Test-data" tabindex="-1">Test data <a class="header-anchor" href="#Test-data" aria-label="Permalink to &quot;Test data {#Test-data}&quot;">​</a></h2><ul><li><p>LEMI-424: <a href="https://webapps.bgs.ac.uk/services/ngdc/accessions/index.html#item182849" target="_blank" rel="noreferrer">British Geological Survey accession</a></p></li><li><p>Metronix ADU survey: <a href="https://github.com/BRGM/razorback-tutorial-data" target="_blank" rel="noreferrer">BRGM razorback tutorial data</a></p></li></ul>`,30)])])}const g=a(l,[["render",n]]);export{c as __pageData,g as default};
